/**
 * Create or update one resource
 *
 * base_revision 0 creates the resource. Any other value updates it, and a value that is not the current revision gets 409, so a stale copy never overwrites a newer save.
 */
export const saveResourceMutation = (options?: Partial<Options<SaveResourceData>>): UseMutationOptions<SaveResourceResponse, SaveResourceError, Options<SaveResourceData>> => {
    const mutationOptions: UseMutationOptions<SaveResourceResponse, SaveResourceError, Options<SaveResourceData>> = {
        mutationFn: async (fnOptions) => {
            const { data } = await saveResource({
                ...options,
                ...fnOptions,
                throwOnError: true
            });
            return data;
        }
    };
    return mutationOptions;
};

